import React from 'react';
import { BarChart3 } from 'lucide-react';

const SalesChart = () => {
  return (
    <div className="bg-gradient-to-br from-white to-white/70 dark:from-neutral-900 dark:to-neutral-900/70 backdrop-blur-xl rounded-xl sm:rounded-2xl p-4 sm:p-6 shadow-lg border border-white/30 dark:border-neutral-800/50">
      <h3 className="text-base sm:text-lg font-bold text-neutral-900 dark:text-white mb-4 sm:mb-6">Performance des ventes</h3>
      <div className="h-48 sm:h-64 flex items-center justify-center rounded-lg sm:rounded-xl bg-gradient-to-br from-neutral-50 to-neutral-100 dark:from-neutral-800 dark:to-neutral-900 border border-neutral-200 dark:border-neutral-700">
        <div className="text-center px-4">
          <BarChart3 className="h-8 sm:h-12 w-8 sm:w-12 text-neutral-400 mx-auto mb-2 sm:mb-4" />
          <p className="text-xs sm:text-sm text-neutral-600 dark:text-neutral-400">Graphique des ventes</p>
        </div>
      </div>
    </div>
  );
};

export default SalesChart;
